            if (length < 0 || mutations == null && length != 0) return DeterministicStatus.OutOfRange;
            if (length == 0) return DeterministicStatus.None;
            var s = Capture(out var backup, true); if (!s.IsSuccess()) return s;
            for (int i = 0; i < length; i++)
            { s = TryApply(mutations[i]); if (!s.IsSuccess()) { var restored = TryRestore(backup); backup.Dispose(); return restored.IsSuccess() ? s : restored; } }
            if (Options.Strategy == SpatialIndexStrategy.StaticBvh && Storage.State.Dirty) s = TryRebuild();
            backup.Dispose(); return s;
        }
